import { expect } from "vitest";
import { outcomes } from "@shivaedev/test-story/server/outcomes.ts";
import { clientModulesProject, importsTheClientList } from "#test/clientModuleTraits.ts";
import { generatedOnce, generator, notesProject } from "#test/generator.ts";

const LIST = "src/generated/client/modules.ts";
const SERVER_LIST = "src/generated/server/modules.ts";
const HEADER =
	"// Generated by @shivaedev/build: the client's module list, every exported `clientModule(...)` outside server code in path order. Do not edit or commit this file; run `pnpm generate` to write it again.";

generator.it(
	"generate lists every exported client module in its file's path order, and neither the server registration nor a kit's module",
	[clientModulesProject()],
	function* ({ generatedFile, generates }) {
		yield* outcomes([
			["generate", () => generates(), { files: { [LIST]: "written", [SERVER_LIST]: "written" }, problems: [], result: "succeeded" }],
			[
				"the client list",
				() => generatedFile(LIST),
				[
					HEADER,
					'import { archiveModule } from "#modules/archive/client/module.tsx";',
					'import { notesModule } from "#modules/notes/client/module.tsx";',
					'import { tagsModule } from "#modules/tags/client/module.tsx";',
					"",
					"export const modules = [",
					"\tarchiveModule,",
					"\tnotesModule,",
					"\ttagsModule,",
					"] as const;",
					"",
				].join("\n"),
			],
			["the server list", () => generatedFile(SERVER_LIST), expect.not.stringContaining("client")],
		]);
	},
);

generator.it(
	"generate writes an empty client list for a project that imports it and has no client module yet",
	[notesProject(), importsTheClientList(), generatedOnce()],
	function* ({ generatedFile }) {
		expect(yield* generatedFile(LIST)).toBe(`${HEADER}\n\nexport const modules = [] as const;\n`);
	},
);

generator.it(
	"after a new module folder gains its client module, generate --check names the stale list and generate adds the module",
	[clientModulesProject(), generatedOnce()],
	function* ({ addsClientModule, generatedFile, generates, generatesWithCheck }) {
		yield* addsClientModule("Labels");

		yield* outcomes([
			[
				"generate --check",
				() => generatesWithCheck(),
				{ files: { [LIST]: "stale" }, problems: [`${LIST} is stale; run \`pnpm generate\``], result: "failed" },
			],
			["generate", () => generates(), { files: { [LIST]: "written" }, problems: [], result: "succeeded" }],
			["the list", () => generatedFile(LIST), expect.stringContaining("\tarchiveModule,\n\tlabelsModule,\n\tnotesModule,\n")],
		]);
	},
);

generator.it(
	"generate lists a client module built through a namespace import",
	[clientModulesProject(), generatedOnce()],
	function* ({ addsClientModule, generatedFile, generates }) {
		yield* addsClientModule("Labels", "through a namespace import");

		yield* outcomes([
			["generate", () => generates(), { files: { [LIST]: "written" }, problems: [], result: "succeeded" }],
			["the list", () => generatedFile(LIST), expect.stringContaining('import { labelsModule } from "#modules/labels/client/module.tsx";')],
		]);
	},
);

const REFUSALS = [
	[
		"exporting something else",
		"src/modules/labels/client/module.tsx",
		"exports no client module, so the client's module list leaves its module out; export the module as a const built by clientModule from @shivaedev/react/client/module.ts",
	],
	[
		"for an admin page exporting something else",
		"src/modules/labels/client/admin/module.tsx",
		"exports no client module, so the client's module list leaves its module out; export the module as a const built by clientModule from @shivaedev/react/client/module.ts",
	],
	[
		"in server code",
		"src/modules/labels/server/clientModule.tsx",
		"exports labelsModule built by clientModule in server code, which the client's module list never imports; move it to the module's client/module.tsx",
	],
] as const;

for (const [shape, file, refusal] of REFUSALS) {
	generator.it(
		`a client module ${shape} stops generate with a message naming its file, and the list stays as it was`,
		[clientModulesProject(), generatedOnce()],
		function* ({ addsClientModule, generatedFile, generates }) {
			const before = yield* generatedFile(LIST);

			yield* addsClientModule("Labels", shape);

			yield* outcomes([
				["generate", () => generates(), { files: { [LIST]: "refused" }, problems: [`${file}: ${refusal}`], result: "failed" }],
				["the list", () => generatedFile(LIST), before],
			]);
		},
	);
}
